"""
xo-projects backup/restore router.

All endpoints under ``/api/xo-projects-sync``. The router is thin: it
maps HTTP requests to ``services.cowork_agent.xo_projects_sync``
functions, translates domain errors into the right HTTP status codes,
and never holds long-running logic itself.

Repo model: each xo-project lives in its own private GitHub repo named
``xo-project-<project_id>``. Repos are created lazily on first backup
of that project — no upfront repo creation at setup.

Auth + config preconditions:
- Every endpoint except ``/setup`` requires ``SyncConfig.configured``
  (passphrase in env) AND a resolvable GitHub token. Failing either
  returns a structured 400/401 with the exact next step the user (or
  the agent on their behalf) needs to take.
- ``/setup`` only persists the passphrase; it does NOT touch GitHub
  repos. The first per-project backup is what creates that project's
  remote.
"""

from __future__ import annotations

import logging

from fastapi import APIRouter, HTTPException
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

from services.cowork_agent.xo_projects_sync import backup as backup_mod
from services.cowork_agent.xo_projects_sync import config as cfg_mod
from services.cowork_agent.xo_projects_sync import crypto, github
from services.cowork_agent.xo_projects_sync import restore as restore_mod


log = logging.getLogger(__name__)
router = APIRouter(prefix="/api/xo-projects-sync", tags=["xo-projects-sync"])


# ── Request bodies ───────────────────────────────────────────────────────────


class SetupBody(BaseModel):
    passphrase: str = Field(..., min_length=1,
                             description="Symmetric encryption passphrase. Required to restore on any machine.")
    confirm_rotation: bool = Field(
        False,
        description=(
            "Required to be true when overwriting an existing, different "
            "passphrase. Rotating the passphrase makes every previously-"
            "encrypted snapshot permanently unrecoverable."
        ),
    )


class BackupBody(BaseModel):
    note: str | None = Field(None, max_length=500,
                              description="Optional short note appended to the commit message.")


class RestoreBody(BaseModel):
    snapshot_id: str | None = Field(None,
                                     description="YYYYMMDD-HHMMSS snapshot id; defaults to latest.")
    force: bool = Field(False,
                         description="Overwrite the local project folder if it exists. Destructive.")


class RestoreAllBody(BaseModel):
    snapshot_id_map: dict[str, str] | None = Field(None,
                                                    description="Per-project snapshot pins; missing projects use latest.")
    force: bool = False


# ── Auth/config helpers ──────────────────────────────────────────────────────


async def _require_config_and_auth() -> tuple[cfg_mod.SyncConfig, github.GitHubAuth, str]:
    """Common precondition for every operation post-setup.

    Returns (config, auth, owner). Raises HTTPException with actionable
    detail when either side is missing. The per-project repo URL is
    derived inside the service layer; there is no shared repo URL.
    """
    cfg = cfg_mod.load_config()
    if not cfg.configured:
        raise HTTPException(400, detail={
            "error": "not_configured",
            "detail": "Backup is not configured.",
            "suggestion": "POST /api/xo-projects-sync/setup with {passphrase} first.",
        })

    try:
        auth = await github.resolve_auth()
    except github.AuthMissingError as exc:
        raise HTTPException(401, detail={
            "error": "github_auth_missing",
            "detail": str(exc),
            "suggestion": (
                "Either complete the GitHub connector flow in xo-cowork UI, "
                f"or add {cfg_mod.ENV_GITHUB_PAT}=<your_token> to xo-cowork-api/.env."
            ),
        })

    try:
        owner = await github.discover_owner(auth)
    except github.GitHubAPIError as exc:
        raise HTTPException(exc.status, detail={
            "error": "github_identity_failed",
            "detail": exc.message,
        })

    return cfg, auth, owner


# ── /setup ───────────────────────────────────────────────────────────────────


@router.post("/setup")
async def setup(body: SetupBody) -> JSONResponse:
    """Bootstrap config. Does NOT create any repos — those are created lazily on first backup.

    Steps:
      1. Verify GPG is installed (we'd fail at first backup otherwise).
      2. Resolve a GitHub token; fail 401 with a clear message if missing.
      3. Discover the owner (lets the response confirm which account we're configured against).
      4. Persist passphrase into xo-cowork-api/.env and os.environ.
    """
    try:
        crypto.check_gpg_available()
    except crypto.GpgUnavailableError as exc:
        raise HTTPException(500, detail={"error": "gpg_missing", "detail": str(exc)})

    # Rotation guardrail: if a passphrase is already set and the caller
    # is trying to replace it with a *different* one, refuse unless the
    # body explicitly confirms. Setting the same passphrase twice is a
    # safe no-op and is allowed without confirmation.
    existing = cfg_mod.load_config()
    if (
        existing.configured
        and existing.passphrase != body.passphrase
        and not body.confirm_rotation
    ):
        raise HTTPException(409, detail={
            "error": "passphrase_already_set",
            "detail": (
                "A backup passphrase is already configured. Re-running "
                "/setup with a different passphrase rotates it — every "
                "existing snapshot was encrypted with the old passphrase "
                "and will be permanently unrecoverable after rotation."
            ),
            "suggestion": (
                "If the user has explicitly confirmed they don't need to "
                "restore from existing snapshots, re-send with "
                "`confirm_rotation: true`. To keep old backups restorable, "
                "restore them under the current passphrase first, then "
                "rotate, then back up again."
            ),
        })

    try:
        auth = await github.resolve_auth()
    except github.AuthMissingError as exc:
        raise HTTPException(401, detail={
            "error": "github_auth_missing",
            "detail": str(exc),
            "suggestion": (
                "Either complete the GitHub connector flow in xo-cowork UI, "
                f"or add {cfg_mod.ENV_GITHUB_PAT}=<your_token> to xo-cowork-api/.env."
            ),
        })

    try:
        owner = await github.discover_owner(auth)
    except github.GitHubAPIError as exc:
        raise HTTPException(exc.status, detail={
            "error": "github_identity_failed",
            "detail": exc.message,
        })

    cfg_mod.upsert_env({cfg_mod.ENV_PASSPHRASE: body.passphrase})

    return JSONResponse({
        "configured": True,
        "repo_owner": owner,
        "token_source": auth.source,
    })


# ── /status ──────────────────────────────────────────────────────────────────


@router.get("/status")
async def status() -> JSONResponse:
    """Lightweight: report current config + token source. No GitHub network calls."""
    cfg = cfg_mod.load_config()
    token_source: str | None
    try:
        auth = await github.resolve_auth()
        token_source = auth.source
    except github.AuthMissingError:
        token_source = None
    try:
        crypto.check_gpg_available()
        gpg_ok = True
    except crypto.GpgUnavailableError:
        gpg_ok = False
    return JSONResponse({
        "configured": cfg.configured,
        "token_source": token_source,
        "gpg_available": gpg_ok,
    })


# ── /projects ────────────────────────────────────────────────────────────────


@router.get("/projects")
async def list_projects_in_repo() -> JSONResponse:
    _cfg, auth, owner = await _require_config_and_auth()
    try:
        projects = await restore_mod.list_remote_projects(auth=auth, owner=owner)
    except github.GitHubAPIError as exc:
        raise HTTPException(exc.status, detail={"error": "github_list_failed", "detail": exc.message})
    except RuntimeError as exc:
        raise HTTPException(502, detail={"error": "git_failed", "detail": str(exc)})
    return JSONResponse([p.to_dict() for p in projects])


# ── /projects/{id} (backup one) ──────────────────────────────────────────────


@router.post("/projects/{project_id}")
async def backup_project(project_id: str, body: BackupBody | None = None) -> JSONResponse:
    cfg, auth, owner = await _require_config_and_auth()
    note = body.note if body else None
    try:
        result = await backup_mod.backup_one(
            project_id, cfg=cfg, auth=auth, owner=owner, note=note,
        )
    except FileNotFoundError as exc:
        raise HTTPException(404, detail={"error": "project_not_found", "detail": str(exc)})
    except github.GitHubAPIError as exc:
        raise HTTPException(502, detail={
            "error": "repo_create_failed",
            "detail": exc.message,
            "suggestion": (
                "Token may lack `repo` scope. Regenerate the PAT with `repo` "
                "scope, or complete `gh auth login` via the UI."
            ),
        })
    except RuntimeError as exc:
        raise HTTPException(502, detail={"error": "backup_failed", "detail": str(exc)})

    if not result.ok:
        raise HTTPException(500, detail={"error": "backup_failed", "detail": result.error})
    return JSONResponse(result.to_dict())


# ── /all (backup all) ────────────────────────────────────────────────────────


@router.post("/all")
async def backup_all_projects(body: BackupBody | None = None) -> JSONResponse:
    cfg, auth, owner = await _require_config_and_auth()
    note = body.note if body else None
    results = await backup_mod.backup_all(
        cfg=cfg, auth=auth, owner=owner, note=note,
    )
    return JSONResponse([r.to_dict() for r in results])


# ── /projects/{id}/restore ───────────────────────────────────────────────────


@router.post("/projects/{project_id}/restore")
async def restore_project(project_id: str, body: RestoreBody | None = None) -> JSONResponse:
    cfg, auth, owner = await _require_config_and_auth()
    snapshot_id = body.snapshot_id if body else None
    force = body.force if body else False
    try:
        result = await restore_mod.restore_one(
            project_id, cfg=cfg, auth=auth, owner=owner,
            snapshot_id=snapshot_id, force=force,
        )
    except restore_mod.ProjectExistsError as exc:
        raise HTTPException(409, detail={
            "error": "project_exists",
            "detail": str(exc),
            "suggestion": "Pass force=true in the body to overwrite; existing local data will be lost.",
        })
    except restore_mod.SnapshotNotFoundError as exc:
        raise HTTPException(404, detail={"error": "snapshot_not_found", "detail": str(exc)})
    except restore_mod.ChecksumMismatchError as exc:
        raise HTTPException(502, detail={"error": "verify_failed", "detail": str(exc)})
    except RuntimeError as exc:
        raise HTTPException(500, detail={"error": "restore_failed", "detail": str(exc)})
    return JSONResponse(result.to_dict())


# ── /all/restore ─────────────────────────────────────────────────────────────


@router.post("/all/restore")
async def restore_all_projects(body: RestoreAllBody | None = None) -> JSONResponse:
    cfg, auth, owner = await _require_config_and_auth()
    snapshot_id_map = body.snapshot_id_map if body else None
    force = body.force if body else False
    results = await restore_mod.restore_all(
        cfg=cfg, auth=auth, owner=owner,
        snapshot_id_map=snapshot_id_map, force=force,
    )
    return JSONResponse([r.to_dict() for r in results])

"""BFF secrets routes — read & edit with curated shape.

Curated wrapper over services/cowork_agent/agent_env via the
SecretsScope handle in services.cowork_agent.scopes. Five routes:

  GET    /api/secrets                  list with masked previews
  GET    /api/secrets/{key}/reveal     raw value for one key
  PUT    /api/secrets                  bulk replace
  PATCH  /api/secrets/{key}            single set/update
  DELETE /api/secrets/{key}            single hard-delete (idempotent)

See docs/bff-endpoints-design.md §9.2 for the full contract.
"""

from __future__ import annotations

import logging
from typing import Optional

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

from routers.cowork_agent.bff.filters import (
    HIDDEN_KEYS,
    is_valid_key,
    is_valid_value,
    preview_value,
)
from services.cowork_agent import scopes

logger = logging.getLogger(__name__)

router = APIRouter()


# ── Pydantic models ───────────────────────────────────────────────────────────


class SecretSummary(BaseModel):
    key: str
    is_set: bool
    preview: Optional[str] = None


class ListSecretsResponse(BaseModel):
    items: list[SecretSummary]
    total: int


class RevealResponse(BaseModel):
    key: str
    value: str


class SecretItem(BaseModel):
    key: str
    value: str


class PutSecretsRequest(BaseModel):
    items: list[SecretItem]


class PatchSecretRequest(BaseModel):
    value: str


class DeleteSecretResponse(BaseModel):
    key: str
    deleted: bool


# ── Helpers ───────────────────────────────────────────────────────────────────


def _shape(entries: list[dict]) -> list[SecretSummary]:
    """Filter on the way out (P4): drop hidden keys, drop malformed
    keys (log WARN), and convert to typed summaries."""
    out: list[SecretSummary] = []
    for e in entries:
        key = (e.get("key") or "").strip()
        if not key:
            continue
        if not is_valid_key(key):
            logger.warning("Skipping malformed key in secrets store: %r", key)
            continue
        if key in HIDDEN_KEYS:
            continue
        value = e.get("value") or ""
        if not is_valid_value(value):
            # Lenient-on-read: surface as is_set=false rather than rejecting.
            out.append(SecretSummary(key=key, is_set=False, preview=None))
            continue
        is_set = bool(value.strip())
        out.append(
            SecretSummary(
                key=key,
                is_set=is_set,
                preview=preview_value(value) if is_set else None,
            )
        )
    out.sort(key=lambda s: s.key)
    return out


def _bad_request(code: str, message: str) -> HTTPException:
    return HTTPException(status_code=400, detail={"code": code, "message": message})


def _not_found() -> HTTPException:
    return HTTPException(
        status_code=404,
        detail={"code": "key_not_found", "message": "Secret not found."},
    )


def _scope_unavailable() -> HTTPException:
    return HTTPException(
        status_code=500,
        detail={
            "code": "scope_unavailable",
            "message": "Secrets store is not accessible.",
        },
    )


def _require_valid_key(key: str) -> None:
    if not is_valid_key(key):
        raise _bad_request("invalid_key", "Key must match ^[A-Z_][A-Z0-9_]*$.")


def _require_valid_value(value: str) -> None:
    if not is_valid_value(value):
        raise _bad_request(
            "invalid_value", "Value must not contain newline or null bytes."
        )


def _require_writable_key(key: str) -> None:
    _require_valid_key(key)
    if key in HIDDEN_KEYS:
        raise _bad_request("invalid_key", "Key is reserved and cannot be modified.")


# ── Routes ────────────────────────────────────────────────────────────────────


@router.get("/api/secrets", response_model=ListSecretsResponse)
def list_secrets() -> ListSecretsResponse:
    handle = scopes.resolve_scope("secrets")
    try:
        entries = handle.load()
    except OSError as exc:
        raise _scope_unavailable() from exc
    items = _shape(entries)
    return ListSecretsResponse(items=items, total=len(items))


@router.get("/api/secrets/{key}/reveal", response_model=RevealResponse)
def reveal_secret(key: str) -> RevealResponse:
    _require_valid_key(key)
    if key in HIDDEN_KEYS:
        raise _not_found()
    handle = scopes.resolve_scope("secrets")
    try:
        entries = handle.load()
    except OSError as exc:
        raise _scope_unavailable() from exc
    entry = next((e for e in entries if e.get("key") == key), None)
    if entry is None:
        raise _not_found()
    return RevealResponse(key=key, value=entry.get("value") or "")


@router.put("/api/secrets", response_model=ListSecretsResponse)
def put_secrets(body: PutSecretsRequest) -> ListSecretsResponse:
    seen: set[str] = set()
    cleaned: list[dict] = []
    for item in body.items:
        key = item.key.strip()
        _require_writable_key(key)
        _require_valid_value(item.value)
        if key in seen:
            raise _bad_request("duplicate_key", f"Duplicate key in items: {key}")
        seen.add(key)
        cleaned.append({"key": key, "value": item.value})

    handle = scopes.resolve_scope("secrets")
    try:
        handle.save(cleaned)
        entries = handle.load()
    except OSError as exc:
        raise _scope_unavailable() from exc
    items = _shape(entries)
    return ListSecretsResponse(items=items, total=len(items))


@router.patch("/api/secrets/{key}", response_model=SecretSummary)
def patch_secret(key: str, body: PatchSecretRequest) -> SecretSummary:
    _require_writable_key(key)
    _require_valid_value(body.value)
    handle = scopes.resolve_scope("secrets")
    try:
        handle.upsert(key, body.value)
    except OSError as exc:
        raise _scope_unavailable() from exc
    is_set = bool(body.value.strip())
    return SecretSummary(
        key=key,
        is_set=is_set,
        preview=preview_value(body.value) if is_set else None,
    )


@router.delete("/api/secrets/{key}", response_model=DeleteSecretResponse)
def delete_secret(key: str) -> DeleteSecretResponse:
    _require_valid_key(key)
    if key in HIDDEN_KEYS:
        return DeleteSecretResponse(key=key, deleted=False)
    handle = scopes.resolve_scope("secrets")
    try:
        deleted = handle.delete(key)
    except OSError as exc:
        raise _scope_unavailable() from exc
    return DeleteSecretResponse(key=key, deleted=deleted)

"""GET /api/xo-projects — BFF list of user projects.

Sits on top of services/cowork_agent/project_layout helpers. Strips the
``path`` field so the frontend never sees absolute filesystem
locations; merges scaffolded and unscaffolded directories into one
sorted list (newest first) and marks each entry with ``unscaffolded``
so the UI can prompt to complete setup.

See docs/bff-endpoints-design.md §9.1 for the full contract.
"""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Optional

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

from routers.cowork_agent.bff.filters import (
    PROJECT_SYSTEM_LEAVES,
    is_hidden_name,
    is_root_only_hidden,
)
from services.cowork_agent import scopes
from services.cowork_agent.project_layout import (
    list_project_tree,
    list_projects,
    list_unscaffolded_dirs,
    project_dir_exists,
)

router = APIRouter()


class Project(BaseModel):
    id: str
    display_name: str
    description: Optional[str] = None
    created_at: Optional[str] = None
    unscaffolded: bool


class ListProjectsResponse(BaseModel):
    items: list[Project]
    total: int


def _to_iso_utc(ts: Optional[float]) -> Optional[str]:
    if ts is None:
        return None
    return (
        datetime.fromtimestamp(ts, tz=timezone.utc)
        .isoformat()
        .replace("+00:00", "Z")
    )


def _shape_scaffolded(entry: dict) -> Project:
    name = str(entry.get("name") or "")
    display = entry.get("display_name") or name
    return Project(
        id=name,
        display_name=str(display),
        description=(entry.get("description") or None),
        created_at=(entry.get("created_at") or None),
        unscaffolded=False,
    )


def _shape_unscaffolded(entry: dict) -> Project:
    name = str(entry.get("name") or "")
    return Project(
        id=name,
        display_name=name,
        description=None,
        created_at=_to_iso_utc(entry.get("mtime")),
        unscaffolded=True,
    )


def _sort_newest_first(items: list[Project]) -> list[Project]:
    """Newest first by created_at; nulls last; alphabetical tiebreak."""
    with_ts = sorted(
        [p for p in items if p.created_at],
        key=lambda p: p.id,
    )
    with_ts.sort(key=lambda p: p.created_at or "", reverse=True)
    without_ts = sorted(
        [p for p in items if not p.created_at],
        key=lambda p: p.id,
    )
    return with_ts + without_ts


@router.get("/api/xo-projects", response_model=ListProjectsResponse)
def list_xo_projects() -> ListProjectsResponse:
    try:
        scopes.resolve_scope("xo-projects")  # validates scope exists
        scaffolded = list_projects()
        unscaffolded = list_unscaffolded_dirs()
    except OSError as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "code": "scope_unavailable",
                "message": "Project directory is not readable.",
            },
        ) from exc

    items: list[Project] = []
    for entry in scaffolded:
        if (entry.get("name") or "") in PROJECT_SYSTEM_LEAVES:
            continue
        items.append(_shape_scaffolded(entry))
    for entry in unscaffolded:
        if (entry.get("name") or "") in PROJECT_SYSTEM_LEAVES:
            continue
        items.append(_shape_unscaffolded(entry))

    items = _sort_newest_first(items)
    return ListProjectsResponse(items=items, total=len(items))


# ── /api/xo-projects/{id}/tree ────────────────────────────────────────────────


class TreeEntry(BaseModel):
    name: str
    relative_path: str


class ProjectTreeResponse(BaseModel):
    project_id: str
    relative_path: str
    parent_relative_path: Optional[str] = None
    dirs: list[TreeEntry]
    files: list[TreeEntry]


def _filter_tree_entries(entries: list[dict], at_root: bool) -> list[TreeEntry]:
    out: list[TreeEntry] = []
    for e in entries:
        name = e.get("name") or ""
        if is_hidden_name(name):
            continue
        if at_root and is_root_only_hidden(name):
            continue
        out.append(TreeEntry(name=name, relative_path=e.get("relative_path") or ""))
    return out


@router.get("/api/xo-projects/{project_id}/tree", response_model=ProjectTreeResponse)
def project_tree(project_id: str, relative_path: str = "") -> ProjectTreeResponse:
    if not project_dir_exists(project_id):
        raise HTTPException(
            status_code=404,
            detail={"code": "project_not_found", "message": "Project not found."},
        )

    try:
        raw = list_project_tree(project_id, relative_path)
    except ValueError as exc:
        raise HTTPException(
            status_code=400,
            detail={
                "code": "invalid_relative_path",
                "message": "relative_path is malformed or escapes the project root.",
            },
        ) from exc
    except OSError as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "code": "scope_unavailable",
                "message": "Project directory is not readable.",
            },
        ) from exc

    if raw is None:
        raise HTTPException(
            status_code=404,
            detail={"code": "directory_not_found", "message": "Directory not found in project."},
        )

    at_root = (raw["relative_path"] or "") == ""
    return ProjectTreeResponse(
        project_id=raw["project_id"],
        relative_path=raw["relative_path"],
        parent_relative_path=raw["parent_relative_path"],
        dirs=_filter_tree_entries(raw["dirs"], at_root),
        files=_filter_tree_entries(raw["files"], at_root),
    )

